def seed_sla_policies(apps, schema_editor):
    SLAPolicy = apps.get_model('core', 'SLAPolicy')
    TicketType = apps.get_model('core', 'TicketType')
    PriorityLevel = apps.get_model('core', 'PriorityLevel')

    # Default SLA matrix — editable by admins later
    matrix = {
        'complaint': {'low': (48, 96, 168), 'medium': (24, 48, 72),
                      'high': (12, 24, 48), 'urgent': (4, 8, 24)},
        'leave': {'low': (24, 48, 72), 'medium': (12, 24, 48),
                  'high': (6, 12, 24), 'urgent': (2, 4, 12)},
        'document': {'low': (72, 120, 168), 'medium': (48, 72, 120),
                     'high': (24, 48, 72), 'urgent': (12, 24, 48)},
        'gatepass': {'low': (12, 24, 48), 'medium': (6, 12, 24),
                     'high': (2, 4, 12), 'urgent': (1, 2, 6)},
    }

    for tt_code, prio_map in matrix.items():
        try:
            tt = TicketType.objects.get(code=tt_code)
        except TicketType.DoesNotExist:
            continue

        for prio_code, (green, yellow, red) in prio_map.items():
            try:
                prio = PriorityLevel.objects.get(code=prio_code)
            except PriorityLevel.DoesNotExist:
                continue

            SLAPolicy.objects.get_or_create(
                ticket_type=tt,
                priority=prio,
                defaults={
                    'green_hours': green,
                    'yellow_hours': yellow,
                    'red_hours': red,
                    'auto_escalate': True,
                    'escalation_after_hours': red,
                    'is_active': True,
                }
            )


